local _, ns = ...
local Translate = ns.Lore.Translate

Translate("deDE", "silverpine-forest", {
	title = "Silberwald",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Silberwald erstreckt sich von den Lichtungen von {link:tirisfal-glades}Tirisfal{/link} nach Süden bis zur großen Mauer von {link:gilneas}Gilneas{/link}. Dunkle Kiefern drängen sich auf seinen Hügeln, und im Osten fallen seine Ufer in das graue Wasser des {red:lordamere-lake}Lordameresees{/red} ab. Einst war er ein stilles Land der Höfe, Obstgärten und Mühlen. Nun ist er ein Land der Toten und der Verfluchten. Die {link:forsaken}Verlassenen{/link} halten seine Straßen vom {link:the-sepulcher}Grabmal{/link} aus, die {link:scourge}Geißel{/link} hält eine Inselfestung im See, und in den Hügeln heulen die Wolfsmenschen eines wahnsinnigen Erzmagiers aus {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet das Jahr, in dem sich die ersten {link:humans}Menschen{/link} im Silberwald niederließen, oder welcher Lord ihn zuerst beanspruchte. Seine Bewohner bestellten die Täler, pflegten Obstgärten und arbeiteten in den Mühlen. Über dem Weiler {link:pyrewood-village}Pyrewood{/link} stand die Burg des edlen Barons {link:baron-silverlaine}Silverlaine{/link}. Als König {link:genn-greymane}Genn Greymane{/link} nach dem {link:second-war}Zweiten Krieg{/link} sein Königreich abriegelte, erhob sich der {link:the-greymane-wall}Greymane-Wall{/link} quer durch den Süden des Waldes, und die Tore von {link:gilneas}Gilneas{/link} schlossen sich dahinter. Das Volk des Silberwalds blieb auf der Nordseite zurück.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die Dunkle Fürstin hat ihrem Leutnant {link:varimathras}Varimathras{/link} die Aufgabe übertragen, die Länder im Süden zu nehmen, und der Silberwald ist der erste Schritt. {link:high-executor-hadrec}Hochexekutor Hadrec{/link} befehligt die Verlassenen am {link:the-sepulcher}Grabmal{/link}, doch seine Feinde sind zahlreich. Rot-Hide-{link:gnolls}Gnolle{/link}, erweckt und gebunden vom verräterischen Magier {link:thule-ravenclaw}Thule Ravenclaw{/link}, tragen Leichen aus {link:tirisfal-glades}Tirisfal{/link} zur {link:fenris-isle}Insel Fenris{/link}. Die Worgen des Erzmagiers {link:archmage-arugal}Arugal{/link} jagen in den Wäldern, und die Dorfbewohner von {link:pyrewood-village}Pyrewood{/link} verwandeln sich jede Nacht in Bestien. In {link:ambermill}Ambermill{/link} arbeiten die {link:the-wizards-of-ambermill}Zauberer von Dalaran{/link} an einem eigenen Geheimnis und bewachen die Straßen mit harter Hand. Am {link:the-greymane-wall}Greymane-Wall{/link} sammeln sich verängstigte menschliche Flüchtlinge vor Toren, die sich nicht öffnen werden.

In diesen Tagen haben die Paladine von {link:tyr-s-watch}Tyr's Watch{/link} einen Gesandten zum Grabmal geschickt, und eine Reisende der {link:skyborne}Skyborne{/link} ist in den Wald gekommen und hat Kummer mitgebracht.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Verlassenen.{/b} Todeswachen, Todespirscher, Apotheker und ein toter Erzmagier aus {link:dalaran}Dalaran{/link}, die alle vom {link:the-sepulcher}Grabmal{/link} aus der Dunklen Fürstin dienen.
• {b}Die {link:scourge}Geißel{/link}.{/b} Die Rot-Hide-{link:gnolls}Gnolle{/link}, die Diener von {link:thule-ravenclaw}Thule Ravenclaw{/link} und die willenlosen Toten der alten Höfe.
• {b}Die Worgen.{/b} Die Moonrage und die Söhne Arugals, wilde Wolfsmenschen, die zum Teil dem Erzmagier von {link:shadowfang-keep}Burg Shadowfang{/link} gehorchen.
• {b}Die Verfluchten von {link:pyrewood-village}Pyrewood{/link}.{/b} Dorfbewohner, die bei Tag {link:humans}Menschen{/link} und bei Nacht Bestien sind.
• {b}{link:the-wizards-of-ambermill}Die Zauberer von Ambermill{/link}.{/b} Magier der {link:kirin-tor}Kirin Tor{/link} und ihre Wachen, weder den Lebenden noch den Toten des Nordens freundlich gesinnt.
• {b}Tiere und Murlocs.{/b} Worgs, graue Bären, große Spinnen und die Vile-Fin-{link:murlocs}Murlocs{/link} am Seeufer.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Seuche.{/b} Im {link:third-war}Dritten Krieg{/link} fegte die Seuche über {link:lordaeron}Lordaeron{/link} hinweg. Die Bauern des nördlichen Silberwalds starben auf ihrem Land und erhoben sich unter der {link:scourge}Geißel{/link}.
• {b}Die Worgen.{/b} Die {link:the-wizards-of-ambermill}Zauberer von Dalaran{/link} bekämpften die Geißel im Wald, und ihre eigenen Toten erhoben sich gegen sie. Gegen den Rat seiner Gefährten rief {link:archmage-arugal}Erzmagier Arugal{/link} Mächte von jenseits der Welt an, und die Worgen kamen. Sie metzelten die Toten nieder und wandten sich dann gegen die Zauberer. Sie nahmen die Burg von {link:baron-silverlaine}Baron Silverlaine{/link} ein, und Arugal machte sie zu seiner eigenen.
• {b}Die Verlassenen.{/b} Mit der Zeit kamen die Verlassenen aus {link:tirisfal-glades}Tirisfal{/link} nach Süden und machten das {link:the-sepulcher}Grabmal{/link} zu ihrer Festung im Wald.]=],
		},
		{
			title = "Überlieferungen des Waldes",
			text = [=[• Die Apotheker sagen, dass vor Zeitaltern eine Seuche jedes Lebewesen in den Gewässern des Lordameresees tötete.
• Drei junge Magier woben einst aus ihren Lehrlingsstäben einen einzigen Stab, als Zeichen der Freundschaft. Einer von ihnen war {link:thule-ravenclaw}Thule Ravenclaw{/link}.
• Ein toter Erzmagier am {link:the-sepulcher}Grabmal{/link} behauptet, dass {link:archmage-arugal}Arugal{/link} nie die Macht besaß, überhaupt einen Worgen zu erschaffen.]=],
		},
	},
})

Translate("deDE", "the-sepulcher", {
	title = "Das Grabmal",
	aliases = { "Grabmal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Grabmal ist die Festung der {link:forsaken}Verlassenen{/link} im {link:silverpine-forest}Silberwald{/link}. Es steht auf einem bewaldeten Hügel im Herzen des Waldes, eine alte Begräbnisstätte, wo nun die Toten über die Welt der Lebenden wachen. Von hier schickt {link:high-executor-hadrec}Hochexekutor Hadrec{/link} seine Todespirscher aus, und die Todeswachen halten die Straßen. Ein toter Erzmagier erforscht den Fluch der Worgen, ein Schattenpriester sammelt jeden Fetzen Nachricht, und ein Apotheker der Vereinigung arbeitet an der neuen Seuche. Fledermäuse tragen Reiter nach Norden nach {link:undercity}Undercity{/link}. In diesen Tagen beherbergt das Grabmal auch einen Gesandten von {link:tyr-s-watch}Tyr's Watch{/link} und eine junge Frau der {link:skyborne}Skyborne{/link}.]=],
		},
	},
})

Translate("deDE", "pyrewood-village", {
	title = "Pyrewood",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Pyrewood ist ein kleines Dorf im Süden des Silberwalds, unterhalb der Mauern von {link:shadowfang-keep}Burg Shadowfang{/link}. Bei Tag sieht es aus wie jeder andere Menschenweiler: ein Rathaus, ein Gasthaus, Schmiede und Schneider bei der Arbeit und {link:the-night-watch}Wächter{/link} in den Straßen. Wenn die Sonne untergeht, werden seine Bewohner zu Worgen. {link:archmage-arugal}Arugal{/link} hat ihnen allen verzauberte Fesseln angelegt, und er beherrscht das Dorf durch dessen eigenen Rat, dessen Mitglieder seine Marionetten sind. Im Gasthaus liegt die Studierstube eines Apothekers, der demselben Fluch verfiel. Eine Todespirscherin versteckt sich im Rathaus und wartet darauf, dass {link:shadow-council}der Rat{/link} heimkehrt.]=],
		},
	},
})

Translate("deDE", "ambermill", {
	title = "Ambermill",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ambermill ist ein Dorf in den Hügeln des südöstlichen Silberwalds, nahe dem Ufer des Lordameresees. Es war nie ein bedeutender Ort. Doch die Magier von {link:dalaran}Dalaran{/link} haben es mit Zauberern, Beschwörern und bewaffneten Wächtern gefüllt, und sie schicken ihm Kisten voller Karten und runenverzierter Anhänger per Wagen aus {link:hillsbrad-foothills}Hillsbrad{/link}. Die Verlassenen glauben zu wissen, warum. Ambermill liegt über einem schlafenden Knoten von Leyenergie, und ein Erzmagier hat daran gearbeitet, ihn zu wecken. Was die {link:kirin-tor}Kirin Tor{/link} mit einer solchen Macht vorhaben, kann niemand am {link:the-sepulcher}Grabmal{/link} sagen.]=],
		},
	},
})

Translate("deDE", "fenris-isle", {
	title = "Insel Fenris",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Insel Fenris liegt im Lordameresee, östlich der verfallenen Fähre. Sie ist die Festung der {link:scourge}Geißel{/link} im {link:silverpine-forest}Silberwald{/link}. Die Rot-Hide-{link:gnolls}Gnolle{/link} wimmeln an ihren Ufern und in ihrer zerfallenen Burg. Ein Boot bringt die Leichen aus {link:tirisfal-glades}Tirisfal{/link} von der Fähre über das Wasser, und auf der Insel dienen diese Leichen ihrem neuen Herrn. Vile-Fin-{link:murlocs}Murlocs{/link} jagen an ihren Stränden, und moosbedeckte Seebestien kriechen durch das Schilf. In letzter Zeit sahen die Todeswachen, wie die Gnolle einen großen Leichnam auf einen Scheiterhaufen am Ufer warfen. Es war der Leichnam eines {link:tauren}Tauren{/link}.]=],
		},
	},
})

Translate("deDE", "fenris-keep", {
	title = "Burg Fenris",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Burg Fenris ist die Festung auf der {link:fenris-isle}Insel Fenris{/link}. {link:thule-ravenclaw}Thule Ravenclaw{/link} herrscht dort mit seinen Rot-Hide-Gnollen. In ihrem Hof, nahe dem alten Stall, begruben die {link:gnolls}Gnolle{/link} einen kopflosen Leichnam in einem unmarkierten Grab. Den Kopf behielten sie als Spielzeug. Er spricht noch. Alaric, der oberste Diener Thules, verbrachte die besten Tage seines Lebens in dieser Burg, und er kennt ihre Geheimnisse, darunter eine verborgene Nische im südwestlichen Turm. In letzter Zeit hielten die Gnolle auch einen lebenden Gefangenen in einem Käfig innerhalb der Mauern.]=],
		},
	},
})

Translate("deDE", "the-decrepit-ferry", {
	title = "Die verfallene Fähre",
	aliases = { "verfallene Fähre" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die verfallene Fähre ist eine alte Anlegestelle am Ufer des Lordameresees, östlich des Grabmals. Sie ist morsch und beinahe vergessen, aber nicht untätig. Diener von {link:thule-ravenclaw}Thule Ravenclaw{/link} bewachen sie, und Rot-Hide-{link:gnolls}Gnolle{/link} kommen und gehen. Im dort vertäuten Boot liegen Haufen von Leichen, für die Reise eingewickelt. Jenseits des Wassers steht ein zweiter Steg auf der {link:fenris-isle}Insel Fenris{/link}. Die Verlassenen haben erfahren, dass die Leichen aus den Massengräbern von {link:tirisfal-glades}Tirisfal{/link} stammen, darunter eine Frau aus {link:brill}Brill{/link} namens Deliah, und dass sie alle ihre Reise auf der Insel beenden.]=],
		},
	},
})

Translate("deDE", "the-dead-field", {
	title = "Das Todesfeld",
	aliases = { "Todesfeld" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Todesfeld ist ein verlassenes Gehöft im nördlichen {link:silverpine-forest}Silberwald{/link}. Die Rot-Hide-{link:gnolls}Gnolle{/link} haben es zu einem Lager gemacht, und die Todespirscher, die es beobachteten, glaubten, die Gnolle rüsteten sich zum Krieg. Die Verlassenen griffen sie mehr als einmal an, und jedes Mal wurden sie von einer Banshee namens Nightlash in die Flucht geschlagen, die den Gnollen mit ihrer Magie zu Hilfe kam. {link:high-executor-hadrec}Hadrec{/link} wollte sie vernichtet sehen. Es heißt, dass Nightlashs Essenz zu Staub zerfällt, wenn sie fällt.]=],
		},
	},
})

Translate("deDE", "the-ivar-patch", {
	title = "Das Ivar-Feld",
	aliases = { "Ivar-Feld" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Ivar-Feld war der Hof eines Mannes namens {link:ivar-the-foul}Ivar{/link}, im äußersten Norden des Silberwalds. Als die Seuche kam, fielen Ivar, der größte Teil seiner Familie und seine Arbeiter ihr zum Opfer und erhoben sich wieder unter der {link:scourge}Geißel{/link}. Ivar spukt noch immer als Ghul in seiner Scheune. Die Todespirscher {link:rane-yorick}Rane{/link} und {link:quinn-yorick}Quinn Yorick{/link} wurden hier auf ihrem Einsatz überfallen, und sie machten sein altes Haus zu ihrem Unterschlupf. Von seinen Fenstern aus hält Rane Wache, während Quinn oben genest.]=],
		},
	},
})

Translate("deDE", "malden-s-orchard", {
	title = "Maldens Obsthain",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Maldens Obsthain liegt im äußersten Nordosten des Silberwalds, nahe der Grenze zu {link:tirisfal-glades}Tirisfal{/link}. Seine Bäume stehen ungepflückt, und wer auch immer in seiner Hütte lebte, ist fort. Worgs füllen nun den Obsthain, so viele, dass ein Todespirscher, der ihn auskundschaften sollte, tagelang in der Hütte gefangen war. Die Worgs beobachteten die Tür und warteten darauf, dass er herauskam. Unter ihnen jagt ein großer schwarzer Worg, den man Gorefang nennt.]=],
		},
	},
})

Translate("deDE", "valgan-s-field", {
	title = "Valgans Feld",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Valgans Feld ist ein Weizenhof im nördlichen {link:silverpine-forest}Silberwald{/link}, gleich nördlich einer Brücke über einen kleinen Fluss. Als {link:archmage-arugal}Erzmagier Arugal{/link} zum ersten Mal in den Wald kam, wohnte er hier. Er ließ Zauberbücher zurück, und die Todespirscher, die sie fanden, konnten sie nicht fortschaffen. Darunter war ein Zauber, den Arugal sein Heilmittel nannte. Worgen streifen nun durch das Land um den Hof.]=],
		},
	},
})

Translate("deDE", "north-tide-s-hollow", {
	title = "North Tide's Hollow",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[North Tide's Hollow ist ein Waldstück gleich nördlich des Grabmals, zum westlichen Meer hin. Die Moonrage-Worgen haben es zu einem ihrer Reviere gemacht. Ihre Vielfraße und ihre Dunkelseelen streifen zwischen den Bäumen umher, und jeder von ihnen trägt eine verzauberte Fessel aus Arugals Hand. Der tote Erzmagier am {link:the-sepulcher}Grabmal{/link} hat diese Fesseln genau untersucht. Sie waren, sagt er, der erste Beweis, dass Arugals Magie schwächer war, als die Welt glaubte.]=],
		},
	},
})

Translate("deDE", "olsen-s-farthing", {
	title = "Olsen's Farthing",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Olsen's Farthing ist ein zerstörtes Gehöft neben der Hauptstraße, südlich des Grabmals. Einst trieb es Handel mit jedem Wagen, der durch den Wald kam. Der Hof ist nun von den Toten überrannt. Plünderer und Sklaven im Dienst von {link:thule-ravenclaw}Thule Ravenclaw{/link} haben sich dort versammelt, und sie fallen über jeden her, der sich nähert. Die Verlassenen müssen jedes Mal an ihnen vorbei, wenn sie die südliche Straße nehmen.]=],
		},
	},
})

Translate("deDE", "the-skittering-dark", {
	title = "Das Huschdunkel",
	aliases = { "Huschdunkel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Huschdunkel ist eine mit Netzen verstopfte Senke im Nordwesten des Silberwalds, nahe dem Meer. Große Moospirscher und Nebelkriecher nisten dort, und Bären streifen an seinen Rändern umher. Die Apotheker des Grabmals schätzen das Blut seiner Spinnen. Vermischt mit einem Gift aus dem Herzen eines grauen Bären ergibt es ein tödliches Elixier, und die Vereinigung hofft, dass es ein Schritt zur neuen Seuche sein wird. Ein verlassener Fischer wirft vom nahen Ufer seine Leine aus, als gingen ihn die Spinnen nichts an.]=],
		},
	},
})

Translate("deDE", "deep-elem-mine", {
	title = "Tiefenfelsmine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Tiefenfelsmine liegt in den Hügeln des mittleren Silberwalds, südöstlich des Grabmals. Arugals Magie breitete sich sogar bis hierher aus, und der eigene Vorarbeiter der Mine, {link:grimson-the-pale}Grimson the Pale{/link}, wurde ihr Opfer. Die Moonrage-Worgen halten nun die Stollen. Die Verlassenen wollen die Mine für den kommenden Krieg, denn ihr Erz würde {link:varimathras}Varimathras{/link}' Vormarsch in den Süden nähren. {link:dalar-dawnweaver}Dalar Dawnweaver{/link} glaubt, dass die Mine der Dunklen Fürstin gehören wird, wenn der Vorarbeiter tot ist.]=],
		},
	},
})

Translate("deDE", "beren-s-peril", {
	title = "Beren's Peril",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Beren's Peril ist eine Höhle in den Hügeln südwestlich von {link:ambermill}Ambermill{/link}, nicht weit von einem Lager der Zauberer Dalarans. Die Verlassenen erfuhren von ihren Spähern, dass sich dort eine Schar Untoter versammelt hatte. Schufter und {link:the-night-watch}Wächter{/link} im Dienst von {link:thule-ravenclaw}Thule Ravenclaw{/link} bereiteten einen Angriff auf das {link:the-sepulcher}Grabmal{/link} selbst vor. {link:shadow-priest-allister}Schattenpriester Allister{/link} wartete nicht, bis sie marschierten. Er schickte seine eigenen Agenten in die Höhle, um zuerst zuzuschlagen.]=],
		},
	},
})

Translate("deDE", "gates-of-shadowfang-keep", {
	title = "Tore von Burg Shadowfang",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[{link:shadowfang-keep}Burg Shadowfang{/link} erhebt sich auf einem Hügel im südlichen {link:silverpine-forest}Silberwald{/link}, gleich nördlich von {link:pyrewood-village}Pyrewood{/link}. Sie war die Burg von {link:baron-silverlaine}Baron Silverlaine{/link}, bis die Worgen sie einnahmen und {link:archmage-arugal}Erzmagier Arugal{/link} sie zu seinem Heim machte. Von der Straße aus zeigt die Burg nur ihre dunklen Mauern. Die Söhne Arugals durchstreifen von hier aus den Wald, große Worgen, die dem Erzmagier als seine Kinder dienen. Die Verlassenen haben Todespirscher hineingeschickt. Keiner von ihnen ist zurückgekehrt.]=],
		},
	},
})

Translate("deDE", "the-greymane-wall", {
	title = "Der Greymane-Wall",
	aliases = { "Greymane-Wall" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Greymane-Wall verläuft quer über den Südrand des Silberwalds und riegelt das Königreich {link:gilneas}Gilneas{/link} nach Norden ab. {link:genn-greymane}König Genn Greymane{/link} errichtete ihn nach dem {link:second-war}Zweiten Krieg{/link}, und seine Tore sind seither verschlossen geblieben, selbst als die Seuche kam. Vor dem Wall haben {link:humans}Menschen{/link}, die aus dem Norden flohen, ein Lager der Verzweifelten errichtet. Viele sind krank. Ein blinder Schmied arbeitet unter ihnen. Worgen und Worgs streifen in der Nähe umher, und die Verlassenen fürchten, dass der Fluch auf die Flüchtlinge übergeht. Die Gilneer haben unmissverständlich klargemacht, dass niemand hindurchgelassen wird.]=],
		},
	},
})

Translate("deDE", "pyrewood-villagers", {
	title = "Die Dorfbewohner von Pyrewood",
	aliases = { "Rat von Pyrewood", "Verfluchte von Pyrewood" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Dorfbewohner von Pyrewood führen zwei Leben. Bei Tag sind sie {link:humans}Menschen{/link}: {link:the-night-watch}Wächter{/link}, Älteste, Schmiede, Schneider und Lederer, die ihrer Arbeit nachgehen. Wenn die Sonne untergeht, ergreift der Fluch des Erzmagiers {link:archmage-arugal}Arugal{/link} sie, und sie werden zu Worgen der Moonrage. Jeder von ihnen trägt eine verzauberte Fessel, die Arugal ihnen angelegt hat.]=],
		},
		{
			title = "Der Rat",
			text = [=[{link:pyrewood-village}Pyrewood{/link} wird noch immer von seinem Rat regiert, acht Ratsherren unter Oberbürgermeister Morrison. Die Verlassenen glauben, dass {link:shadow-council}der Rat{/link} nicht mehr sein eigener Herr ist. {link:archmage-arugal}Arugal{/link} benutzt sie als Marionetten, um die Bestien des Dorfes gehorsam zu halten, während seine Aufmerksamkeit {link:shadowfang-keep}Burg Shadowfang{/link} gilt. {link:deathstalker-faerleia}Todespirscherin Faerleia{/link} hoffte, dass sich die Worgen, wäre der Rat tot, gegen Arugal selbst wenden würden.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik verzeichnet, ob sich die Dorfbewohner bei Tag an das erinnern, was sie bei Nacht tun. Es ist nicht geschrieben, wann der Fluch zuerst über sie kam.]=],
		},
	},
})

Translate("deDE", "the-wizards-of-ambermill", {
	title = "Die Zauberer von Ambermill",
	aliases = { "Zauberer von Dalaran", "Kirin Tor von Ambermill" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Zauberer von Ambermill sind Magier aus {link:dalaran}Dalaran{/link} und die Diener, die sie bewachen: Lehrlinge, Beschwörer, Magier, Beobachter, {link:the-night-watch}Wächter{/link} und Beschützer, sogar ein Braumeister und ein Bergmann. Sie unterstehen den {link:kirin-tor}Kirin Tor{/link}, und sie haben ein verschlafenes Dorf des Silberwalds zu einer eigenen Festung gemacht.]=],
		},
		{
			title = "Ihr Werk",
			text = [=[{link:ambermill}Ambermill{/link} liegt auf einem Knoten von Leyenergie, der lange geruht hat. Die {link:kirin-tor}Kirin Tor{/link} wählten es aus diesem Grund, und ihr {link:archmage-ataeric}Erzmagier Ataeric{/link} hat seine Energien für einen großen Zweck wachgewoben. Die runenverzierten Anhänger, die sie tragen, sind alte Werkzeuge der Kirin Tor, mit denen sich solche Macht lenken lässt. Die Zauberer unterhalten auch ein Lager nördlich von {link:pyrewood-village}Pyrewood{/link}, wo ihre Kisten aus {link:hillsbrad-foothills}Hillsbrad{/link} ankommen.]=],
		},
		{
			title = "Zwischen den Lebenden und den Toten",
			text = [=[Für die Verlassenen ist {link:ambermill}Ambermill{/link} das Herz des menschlichen Widerstands im Wald. Die Zauberer halten Wache an den Straßen, seit die große Barriere Dalarans fiel, und sie lassen niemanden frei passieren. Was auch immer sie fürchten, sie sagen es nicht.]=],
		},
	},
})

Translate("deDE", "dalar-dawnweaver", {
	title = "Dalar Dawnweaver",
	subtitle = "Erzmagier der Verlassenen",
	found = "Das Grabmal",
	hint = [=[Sprecht mit dem toten Erzmagier, der am Grabmal Arugals Fluch erforscht.]=],
	allegiance = "Verlassene · einst die Kirin Tor",
	aliases = { "Dalar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dalar Dawnweaver war zu Lebzeiten ein Erzmagier von {link:dalaran}Dalaran{/link}. Einst warnte er die {link:kirin-tor}Kirin Tor{/link}, und sie hörten nicht auf ihn. Nun dient er der Dunklen Fürstin am {link:the-sepulcher}Grabmal{/link}. Er verachtet {link:archmage-arugal}Arugal{/link} offen. Er nennt ihn einen Scharlatan, der schwache Zauber mit verzaubertem Tand stützte und niemals für die Kirin Tor hätte sprechen dürfen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Dalar ist der Gelehrte der Verlassenen für den Fluch der Worgen. In letzter Zeit ist er zu einem kühnen Schluss gelangt: {link:archmage-arugal}Arugal{/link} konnte die Bestien binden, aber er hat sie nie erschaffen, und der Fluch breitet sich auf andere Weise aus.]=],
		},
	},
	chapters = {
		{
			title = "Ein entlarvter Betrüger",
			hint = "Bringt dem toten Erzmagier Beweise vom Greymane-Wall.",
			text = [=[Dalar arbeitete sich durch die Fesseln, die Zauberbücher und die Überreste der Bestien, bis er sich sicher war. Arugals berühmter Fluch war zu schwach, um länger als ein paar Augenblicke anzuhalten. Dalar lachte, denn er hatte den Erzmagier als Betrüger entlarvt. Dann sah er den Preis: Auch das Heilmittel war wertlos.]=],
		},
	},
	mentions = {
		{ text = "Beweist Euren Wert" },
