			text = [=[• Er beschlagnahmte eine Kiste mit Karten und Anhängern, die für {link:ambermill}Ambermill{/link} bestimmt war.
• Er befahl den Tod des Erzmagiers, der die Leyenergien wob.
• Er schrieb ein Buch gegen die Kirche des Lichts, das weit gereist ist.]=],
		},
	},
	mentions = {
