		{
			title = "Zusammenfassung",
			text = [=[Thule Ravenclaw war vor dem {link:third-war}Dritten Krieg{/link} ein junger Magier von großer Verheißung. Mit {link:bethor-iceshard}Bethor Iceshard{/link} und {link:gunther-arcanus}Gunther Arcanus{/link} wob er aus ihren Lehrlingsstäben einen Stab, ein Zeichen ihrer Freundschaft. Als der Lichkönig sich erhob, verriet Thule sie und schloss sich der {link:scourge}Geißel{/link} an. Nun herrscht er über {link:fenris-keep}Burg Fenris{/link}. Mit Hexenmeister- und Nekromantenmagie erschuf er die Rot-Hide-{link:gnolls}Gnolle{/link}, und er schickt sie gegen die {link:forsaken}Verlassenen{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Thule ist die größte Macht der {link:scourge}Geißel{/link} im {link:silverpine-forest}Silberwald{/link}. Er enthauptete sogar seinen eigenen Diener Alaric, den seine Magie an ein endloses Unleben gebunden hatte.]=],
		},
		{
			title = "Taten",
			text = [=[• Er stahl den gewobenen Stab und versteckte ihn in {link:fenris-keep}Burg Fenris{/link}.]=],
		},
	},
	mentions = {
		{ text = "Thule Ravenclaw" },
