		{ text = "Ein Stab für {link:bethor-iceshard}Bethor{/link}" },
		{ text = "Sturm auf die {link:fenris-isle}Insel Fenris{/link}" },
	},
	bonds = {
		{ id = "bethor-iceshard", name = "Bethor Iceshard", note = "sein verratener Freund" },
		{ id = "gunther-arcanus", name = "Gunther Arcanus", note = "sein verratener Freund" },
		{ id = "high-executor-hadrec", name = "Hochexekutor Hadrec", note = "will seinen Kopf" },
	},
})

