Translate("deDE", "lumina-windsinger", {
	title = "Lumina Windsinger",
	subtitle = "Windshaper der Skyborne",
	found = "Das Grabmal, nach ihrer Rettung aus Burg Fenris",
	hint = [=[Sucht die himmelsberührte Elfe, die am Grabmal Zuflucht gefunden hat.]=],
	allegiance = "Windshapers · Gast des Irdenen Rings",
	aliases = { "Lumina" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lumina Windsinger gehört zu den {link:skyborne}Skyborne{/link}, zu dem Volk, das man die {link:windshapers}Windshapers{/link} nennt. Sie kam als Gast des {link:earthen-ring}Irdenen Rings{/link} in diese Lande. Mit dem {link:tauren}Tauren{/link} Banon durchquerte sie den {link:silverpine-forest}Silberwald{/link} in Richtung {link:arathi-highlands}Arathihochland{/link}. Auf der Straße schlug ein Worgen zu. Banon warf sich vor sie und wurde gebissen. Dann fanden die {link:gnolls}Gnolle{/link} sie. Lumina wurde in {link:fenris-keep}Burg Fenris{/link} in einen Käfig gesperrt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Lumina sah den Fluch am Werk. Am Ende erkannte Banon sie und erhob sich dennoch, um sie zu schlagen. Sie hat beim Himmel geschworen, den Worgen zu vernichten, der ihn verdammte.]=],
		},
	},
	chapters = {
		{
			title = "Die Schuld",
			hint = "Hört Luminas Geschichte am Grabmal.",
			text = [=[Die Bestie war Old Fire-Eye, der größte der Worgen des Südens, der nicht tot bleiben wollte. Eine Klinge aus Mondsilber wurde geschmiedet, um ihm ein Ende zu bereiten.]=],
		},
	},
	mentions = {
		{ text = "Lumina Windsinger" },
		{ text = "Der Zorn der {link:windshapers}Windshaper{/link}" },
		{ text = "Old Fire-Eye" },
	},
	bonds = {
		{ id = "trevan-rol", name = "Trevan Rol", note = "folgte ihrer Spur" },
	},
})

Translate("deDE", "tabitha-heartweaver", {
