	hint = [=[Sprecht mit der verlassenen Frau am Grabmal, die auf ihren Mann wartet.]=],
	allegiance = "Verlassene",
	aliases = { "Tabitha" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tabitha Heartweaver wartet am {link:the-sepulcher}Grabmal{/link} auf ihren Mann Edward. Ihr Sohn ging verloren, als {link:arthas-menethil}Arthas{/link} die {link:capital-city}Hauptstadt{/link} von {link:lordaeron}Lordaeron{/link} schleifte, und sein Leichnam wurde nie gefunden. Edward kann es sich nicht verzeihen. Jede Woche geht er zum Friedhof in den Ruinen, um zu suchen, obwohl die Ruinen überrannt sind. Diesmal ist er nicht zurückgekommen.]=],
