	mentions = {
		{ text = "Eine verängstigte Bitte" },
	},
	bonds = {
		{ id = "ruins-of-lordaeron", name = "Ruinen von Lordaeron", note = "wohin ihr Mann ging" },
	},
})

Translate("deDE", "genn-greymane", {
	title = "Genn Greymane",
	subtitle = "König von Gilneas",
	found = "Hinter dem Greymane-Wall, in Gilneas",
	hint = [=[Erfahrt von dem König, dessen Wall den Süden des Silberwalds abriegelt.]=],
	allegiance = "Königreich Gilneas",
	aliases = { "Greymane", "König Greymane", "König Genn Greymane" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Genn Greymane ist der König von {link:gilneas}Gilneas{/link}. Er ist ein stolzer und starrsinniger Herrscher, ein Krieger, der seinem eigenen Volk vertraut und wenigen anderen. Er war es, der Gilneas nach dem {link:second-war}Zweiten Krieg{/link} aus der {link:alliance}Allianz{/link} zurückzog, und er war es, der den großen Wall quer durch den Süden des Silberwalds errichtete. Hinter diesem Wall hat sein Königreich während all des Verderbens im Norden seinen eigenen Rat gehalten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Greymane ist der Herrscher, der sich entschied, allein zu stehen. Sein Wall ersparte {link:gilneas}Gilneas{/link} die Kosten der Kriege anderer Nationen. Er ließ auch den Norden ohne das gilneische Heer der {link:scourge}Geißel{/link} gegenübertreten. Ob der Wall sein Königreich rettete oder es nur verbarg, kann niemand draußen sagen.]=],
		},
		{
			title = "Taten",
			text = [=[• Als {link:stormwind-city}Stormwind{/link} fiel, kam er mit den anderen menschlichen Herrschern zu dem Rat in {link:lordaeron}Lordaeron{/link}, den König {link:terenas-menethil}Terenas{/link} einberufen hatte. Er bezweifelte die Gefahr und prahlte, das Heer von {link:gilneas}Gilneas{/link} könne jeder Bedrohung begegnen.
• Er trat der {link:alliance}Allianz von Lordaeron{/link} nur widerwillig bei und gab ihr weit weniger, als sein Reich hätte geben können.
• Nach dem Krieg stritt er mit seinen Mitkönigen über die Kosten der {link:internment-camps}Internierungslager{/link} der {link:orcs}Orcs{/link} und von {link:nethergarde-keep}Burg Nethergarde{/link}. Als er sich über die Kosten der Burg beklagte, antwortete ihm der junge König {link:varian-wrynn}Varian Wrynn{/link}, dass man ihrer Sicherheit keinen Preis setzen könne.
• Er suchte beim Schicksal des führerlosen {link:alterac-mountains}Alterac{/link} mitzureden und unterstützte einen Anwärter auf dessen Thron.
• Er zog Gilneas aus der Allianz zurück, baute den {link:the-greymane-wall}Greymane-Wall{/link} und schloss seine Tore.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Seit seine Tore geschlossen wurden, ist kein Wort aus {link:gilneas}Gilneas{/link} gedrungen. Was König Greymane von den Worgen vor seiner Tür weiß und was in seinem Königreich geschieht, kann keine Chronik dieser Tage sagen.]=],
		},
	},
	chapters = {
		{
			title = "Der Wall seines Namens",
			hint = "Steht vor dem Wall, der den Namen des Königs trägt.",
			text = [=[Greymane glaubte, dass {link:gilneas}Gilneas{/link} den Kriegen anderer Reiche nichts schuldete. Als die {link:alliance}Allianz{/link} sein Volk bat, für die Gefangenenlager der {link:orcs}Orcs{/link} zu zahlen, weigerte er sich, und er führte sein Königreich ganz aus der Allianz hinaus. Dann mauerte er es ab. {link:the-greymane-wall}Der Greymane-Wall{/link} erhob sich über die Nordgrenze von Gilneas. Als die Seuche nach {link:lordaeron}Lordaeron{/link} kam, blieben seine Tore verschlossen. Kein gilneisches Heer marschierte nach Norden, um dem sterbenden Königreich zu helfen.]=],
		},
		{
			title = "Die verschlossenen Tore",
			hint = [=[Helft den Verlassenen, die Ausbreitung des Fluchs unter den Flüchtlingen am Wall aufzuhalten.]=],
			text = [=[Nun drängen sich Flüchtlinge aus dem Norden am Fuß des Walls, krank und hungrig. Sie hofften, in {link:gilneas}Gilneas{/link} Zuflucht zu finden. Die Gilneer haben unmissverständlich klargemacht, dass sie niemanden hindurchlassen werden. Die Verlassenen, die den Fluch der Worgen fürchten, finden das tröstlich. Sie sagen, dass der Fluch wenigstens die Tore nicht passieren kann.]=],
		},
	},
	mentions = {
		{ text = "Haltet die Ausbreitung auf" },
	},
	bonds = {
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "berief den Rat ein, dem er beitrat" },
		{ id = "the-greymane-wall", name = "Der Greymane-Wall", note = "sein Werk" },
	},
})
